// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Differential guards for MINUS whose operands share no variables statically, pinning native-vs-interpreted parity for
 * the shapes where a compile-time "no shared variables → drop the MINUS" rewrite was suspected of diverging
 * (gap-analysis B2). Verified against the generic evaluator: prepared-query bindings are inlined as constants rather
 * than threaded into the operands' solution domains, and the correlated OPTIONAL form also stays in parity — so these
 * tests document the contract rather than a live defect. If the interpreted engine's binding threading ever changes
 * (e.g. join-algorithm-dependent evaluation of a nested Difference), these guards catch the divergence.
 */
public class LmdbNativeMinusEntryBindingTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			IRI q = vf.createIRI(EX, "q");
			conn.add(vf.createIRI(EX, "x1"), p, vf.createLiteral("n1"));
			conn.add(vf.createIRI(EX, "x2"), p, vf.createLiteral("n2"));
			conn.add(vf.createIRI(EX, "x2"), q, vf.createIRI(EX, "e2"));
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	/**
	 * Prepared-query bindings are inlined as constants by the optimizer rather than threaded into the MINUS operands'
	 * solution domains, so the interpreted engine keeps the left row (verified against this repo's generic evaluator).
	 * The native engine must agree whichever mechanism it uses.
	 */
	@Test
	public void entryBindingOnStaticallyDisjointMinusMatchesInterpreted() {
		String query = "SELECT ?s ?prop ?obj WHERE { ?s ?prop ?obj MINUS { ?a ?b ?c } } ORDER BY ?s ?prop ?obj";
		IRI boundS = iri("x1");

		List<String> generic = genericRows(query, "s", boundS);
		assertThat(generic)
				.as("interpreted engine: prepared bindings are inlined, not threaded — the left row survives")
				.hasSize(1);
		assertThat(rows(query, "s", boundS))
				.as("native rows must match the interpreted engine under an entry binding")
				.isEqualTo(generic);
	}

	/**
	 * The correlated form is the shape most likely to diverge if binding threading ever reaches a nested Difference:
	 * were the outer ?x threaded into both operands' solution domains, the inner rows would be removed. Verified in
	 * parity today; this guard exists to catch any future change on either side.
	 */
	@Test
	public void correlatedDisjointMinusUnderOptionalMatchesInterpreted() {
		String query = "SELECT ?x ?m WHERE { ?x <http://example.com/p> ?n"
				+ " OPTIONAL { { ?x <http://example.com/q> ?m } MINUS { ?a ?b ?c } } } ORDER BY ?x ?m";

		List<String> generic = genericRows(query, null, null);
		assertThat(rows(query, null, null))
				.as("native rows must match the interpreted engine for a correlated statically-disjoint MINUS")
				.isEqualTo(generic);
	}

	/** The all-constant right operand variant of the same suspected shape. */
	@Test
	public void entryBindingOnConstantRightArmMinusMatchesInterpreted() {
		String query = "SELECT ?s ?prop ?obj WHERE { ?s ?prop ?obj"
				+ " MINUS { <http://example.com/x1> <http://example.com/p> \"n1\" } } ORDER BY ?s ?prop ?obj";
		IRI boundS = iri("x2");

		List<String> generic = genericRows(query, "s", boundS);
		assertThat(rows(query, "s", boundS))
				.as("native rows must match the interpreted engine for a constant right arm under an entry binding")
				.isEqualTo(generic);
	}

	/** Without entry bindings the domains stay disjoint and the MINUS removes nothing — the control case. */
	@Test
	public void withoutEntryBindingsDisjointMinusKeepsEveryRow() {
		String query = "SELECT ?s ?prop ?obj WHERE { ?s ?prop ?obj MINUS { ?a ?b ?c } } ORDER BY ?s ?prop ?obj";

		List<String> generic = genericRows(query, null, null);
		assertThat(generic).as("disjoint domains: nothing is removed").hasSize(3);
		assertThat(rows(query, null, null))
				.as("native rows must match the interpreted engine without entry bindings")
				.isEqualTo(generic);
	}

	private IRI iri(String localName) {
		return repository.getValueFactory().createIRI(EX, localName);
	}

	private List<String> rows(String query, String bindingName, Value bindingValue) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(query);
			if (bindingName != null) {
				tupleQuery.setBinding(bindingName, bindingValue);
			}
			return QueryResults.asList(tupleQuery.evaluate())
					.stream()
					.map(LmdbNativeMinusEntryBindingTest::render)
					.collect(Collectors.toList());
		}
	}

	private List<String> genericRows(String query, String bindingName, Value bindingValue) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query, bindingName, bindingValue);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining("|"));
	}
}
